using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class FreightOperationsTests
{
    static readonly EntityId Home=new("site:castle"),Source=new("site:kofu"),Carrier=new("created:freight-carrier"),Job=new("request:letters-freight");
    internal static WorldSession Start(){var seed=NpcFreightTests.Start().DiagnosticSnapshot().NewGame!;return new(NewGameWorld.Create(seed.Start,seed.Registered,seed.Selected.Value,1,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:FreightOperations.Policy));}
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long to){while(s.Seconds<to){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(to,100000);Assert.True(s.Seconds>old);}}
    static void Assign(WorldSession s)=>Good(s.ManageHouseFreight(new(Job,HouseFreightAction.Dispatch,Home:Home,Source:Source,Commodity:"wood",Quantity:10,Advance:200){Carrier=Carrier},s.PlayerControl,s.Revision));
    static HouseFreightJob Current(WorldSession s)=>HouseLogistics.FreightJobs(s.DiagnosticSnapshot(),s.Seconds,s.Revision+1).Single();
    static long Arrival(WorldSession s)=>s.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier).Legs[^1].EndAt;
    static CommandResult Cancel(WorldSession s,long meet,string id="request:cancel-freight")=>s.ManageFreightLetters(new(new(id),Job,FreightLetterAction.Cancel,Source,meet),s.PlayerControl,s.Revision);
    [Fact]public void PostingCancellationDoesNotInstantlyStopCarrierOrRefundCash(){var s=Start();Assign(s);long at=FreightOperations.SuggestedMeeting(s.DiagnosticSnapshot(),Job,Source);Good(Cancel(s,at));Assert.Empty(s.DiagnosticSnapshot().FreightOperations!.Receipts);Assert.Equal(HouseFreightPhase.Outbound,Current(s).Phase);Assert.Equal(300,s.HouseTreasuryView()!.HouseCash);Advance(s,62);Assert.NotEmpty(s.DiagnosticSnapshot().Branches!.Journeys);Assert.Empty(s.DiagnosticSnapshot().FreightOperations!.Receipts);}
    [Fact]public void ReceiptAtSourceBeforePurchaseStopsBuyingAndActualReturnRefunds(){var s=Start();Assign(s);Good(Cancel(s,FreightOperations.SuggestedMeeting(s.DiagnosticSnapshot(),Job,Source)));Advance(s,62);long at=Arrival(s);Advance(s,at);Assert.Single(s.DiagnosticSnapshot().FreightOperations!.Receipts);Assert.DoesNotContain(s.DiagnosticSnapshot().HouseFreight!.Entries,e=>e.Input.Action==HouseFreightAction.Buy);Assert.Equal(HouseFreightPhase.ReturnRequired,Current(s).Phase);Advance(s,at+120);long end=s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Carrier).Legs[^1].EndAt;Advance(s,end+120);Assert.Equal(HouseFreightPhase.Returned,Current(s).Phase);Assert.Equal(500,s.HouseTreasuryView()!.HouseCash);Assert.Equal(20,s.HouseTreasuryView()!.Materials.Wood);}
    [Fact]public void PurchaseStatusIsSealedAndRetainsOriginalObservationAfterOpening(){var s=Start();Assign(s);Advance(s,62);Advance(s,Arrival(s)+60);var p=s.DiagnosticSnapshot().FreightOperations!.Papers.Single(p=>p.Kind==FreightOperations.ReportKind);Assert.Equal(10,p.Observation!.Cargo);Assert.Null(s.DelegatedFreightView().Single().Report);Assert.Equal(ResultCode.NotAvailable,s.Open(s.PlayerControl,new(p.Id),s.Revision).Code);long due=s.DiagnosticSnapshot().Messaging.Attempts.Single(a=>a.MessageId==p.Id).DueAt;Advance(s,due);Assert.Null(s.DelegatedFreightView().Single().Report);Good(s.Open(s.PlayerControl,new(p.Id),s.Revision));var known=s.DelegatedFreightView().Single().Report;Assert.Equal(p.Observation,known);Assert.True(known!.ObservedAt<due);Advance(s,due+120);Assert.Equal(known,s.DelegatedFreightView().Single().Report);}
    [Fact]public void FailedRendezvousDoesNotCancelTheJob(){var s=Start();Assign(s);Good(Cancel(s,1));Advance(s,62);long at=Arrival(s);Advance(s,at+60);Assert.Empty(s.DiagnosticSnapshot().FreightOperations!.Receipts);Assert.Equal(10,Current(s).Cargo);Assert.Contains(s.DiagnosticSnapshot().Messaging.Attempts,a=>a.MessageId.StartsWith("message:freight-cancel/")&&a.Status==AttemptStatus.Lost);}
    [Fact]public void LateCancellationDoesNotUndoAlreadyPurchasedCargo(){var s=Start();Assign(s);Advance(s,62);long at=checked((Arrival(s)+59)/60*60);Good(Cancel(s,at+1));Advance(s,at);Assert.Equal(10,Current(s).Cargo);Advance(s,at+1);Assert.Equal(10,Current(s).Cargo);Assert.Equal(140,Current(s).Cash);Assert.Single(s.DiagnosticSnapshot().FreightOperations!.Receipts);Assert.Equal(HouseFreightPhase.ReturnRequired,Current(s).Phase);}
    [Fact]public void RepeatedConflictingAndStaleCancellationCannotSendTwice(){var s=Start();Assign(s);long rev=s.Revision,at=FreightOperations.SuggestedMeeting(s.DiagnosticSnapshot(),Job,Source);Good(Cancel(s,at));Assert.Equal(ResultCode.AlreadyAccepted,Cancel(s,at).Code);Assert.Equal(ResultCode.IdPayloadConflict,Cancel(s,at+1).Code);Assert.Equal(ResultCode.StateChanged,s.ManageFreightLetters(new(new("request:stale-letter"),Job,FreightLetterAction.Cancel,Source,at),s.PlayerControl,rev).Code);Assert.Single(s.DiagnosticSnapshot().FreightOperations!.Papers);}

    [Fact]public void CancellationAcknowledgementIsAlsoASealedPhysicalReport(){var s=Start();Assign(s);Good(Cancel(s,FreightOperations.SuggestedMeeting(s.DiagnosticSnapshot(),Job,Source)));Advance(s,62);Advance(s,Arrival(s));var p=s.DiagnosticSnapshot().FreightOperations!.Papers.Single(p=>p.Kind==FreightOperations.AckKind);Assert.Equal(ResultCode.NotAvailable,s.Open(s.PlayerControl,new(p.Id),s.Revision).Code);long due=s.DiagnosticSnapshot().Messaging.Attempts.Single(a=>a.MessageId==p.Id).DueAt;Advance(s,due);Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,p.Id,s.PlayerControl.Value));Good(s.Open(s.PlayerControl,new(p.Id),s.Revision));Assert.True(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,p.Id,s.PlayerControl.Value));}
    [Fact]public void KnownFailureAllowsResendButDoesNotUndoSettledCargo(){var s=Start();Assign(s);Good(Cancel(s,1));Advance(s,62);long end=Arrival(s);Advance(s,end+120);var w=s.DiagnosticSnapshot();var original=w.FreightOperations!.Papers.Single(p=>p.Kind==FreightOperations.CancelKind);Assert.Contains(w.Messaging.Messages,m=>m.Kind=="delivery-failure"&&w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==original.Id)&&MessageFlow.Knows(w.Messaging,m.Id,s.PlayerControl.Value));long homeAt=w.Branches!.Journeys.Last(j=>j.Actor==Carrier).Legs[^1].EndAt+1;Good(s.ManageFreightLetters(new(new("request:resend-cancel"),Job,FreightLetterAction.ResendCancellation,Home,homeAt,original.Id),s.PlayerControl,s.Revision));Advance(s,homeAt+120);Assert.Equal(2,s.DiagnosticSnapshot().FreightOperations!.Papers.Count(p=>p.Kind==FreightOperations.CancelKind));Assert.Equal(10,s.DiagnosticSnapshot().Materials!.Houses.Single(h=>h.Site==Home).Wood-20);Assert.Equal(440,s.HouseTreasuryView()!.HouseCash);Assert.Equal(HouseFreightPhase.Completed,Current(s).Phase);}
    [Fact]public void ResendBeforeKnowingFailureAndImpersonationAreAtomic(){var s=Start();Assign(s);Good(Cancel(s,1));var original=s.DiagnosticSnapshot().FreightOperations!.Papers.Single().Id;var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageFreightLetters(new(new("request:premature-resend"),Job,FreightLetterAction.ResendCancellation,Home,86400,original),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageFreightLetters(new(new("request:wrong-sender"),Job,FreightLetterAction.Cancel,Source,86400),Carrier,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedReportTimeQuantityOrPhysicalReceiptCannotLoad(int change){var s=Start();Assign(s);Advance(s,62);Advance(s,Arrival(s)+60);var w=s.DiagnosticSnapshot();var report=w.FreightOperations!.Papers.Single(p=>p.Kind==FreightOperations.ReportKind);if(change<2){w.FreightOperations=w.FreightOperations with{Papers=w.FreightOperations.Papers.Select(p=>p.Id==report.Id?p with{Observation=change==0?p.Observation! with{ObservedAt=0}:p.Observation! with{Cargo=999}}:p).ToArray()};}else{w.FreightOperations=w.FreightOperations with{Receipts=[new(report.Id,s.Seconds,s.Revision)]};}Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ActualV13WorldRetainsBytesAndCannotGainLetters(){var s=NpcFreightTests.Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("FreightOperations",System.Text.Encoding.UTF8.GetString(b));Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.ManageFreightLetters(new(new("request:legacy-letter"),Job,FreightLetterAction.Cancel,Source,86400),s.PlayerControl,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ActualGenerationRecoveryPreservesSealedLettersReceiptAndFuture(int phase)
    {
        var a=Start();Assign(a);if(phase<3)Good(Cancel(a,FreightOperations.SuggestedMeeting(a.DiagnosticSnapshot(),Job,Source)));if(phase>0)Advance(a,62);if(phase>=2)Advance(a,Arrival(a)+60);if(phase>=3){var p=a.DiagnosticSnapshot().FreightOperations!.Papers.Single(p=>p.Kind==FreightOperations.ReportKind);Advance(a,a.DiagnosticSnapshot().Messaging.Attempts.Single(q=>q.MessageId==p.Id).DueAt);if(phase==4)Good(a.Open(a.PlayerControl,new(p.Id),a.Revision));}
        a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"freight-letters-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"letters",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("letters"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.DelegatedFreightView()),ContractJson.Write(b.DelegatedFreightView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"freight-letters-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"freight-letters-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var q in new[]{a,b}){if(phase==0)Advance(q,62);if(phase<2)Advance(q,Arrival(q)+120);if(!HouseLogistics.Closed(Current(q))){Advance(q,q.Seconds+120);long actualReturn=q.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Carrier).Legs[^1].EndAt;Advance(q,Math.Max(q.Seconds,actualReturn)+120);}Advance(q,q.Seconds+2*86400);}Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(phase<3?HouseFreightPhase.Returned:HouseFreightPhase.Completed,Current(a).Phase);
    }

    [Fact]public void SenderRetriesKnownRoadFailureAtMostThreeTimesWithSameObservation(){var plan=Start();Assign(plan);long blockAt=FreightOperations.SuggestedMeeting(plan.DiagnosticSnapshot(),Job,Source);var w=Start().DiagnosticSnapshot();w.Couriers=w.Couriers! with{Conditions=BranchRoutes.GraphEdges(w).Select(e=>new RoadCondition(blockAt,e.Id,true)).ToArray()};var s=new WorldSession(w);Assign(s);Advance(s,62);Assert.Equal(blockAt,Arrival(s));Advance(s,blockAt+300);var papers=s.DiagnosticSnapshot().FreightOperations!.Papers.Where(p=>p.Kind==FreightOperations.ReportKind).ToArray();Assert.Equal(3,papers.Length);Assert.All(papers,p=>Assert.Equal(papers[0].Observation,p.Observation));Assert.All(papers,p=>Assert.Equal(papers[0].Observation!.ObservedAt,p.Observation!.ObservedAt));Assert.True(papers[0].Observation!.ObservedAt>=blockAt);Assert.True(papers[^1].At>blockAt);Assert.Equal(10,Current(s).Cargo);Assert.Null(s.DelegatedFreightView().Single().Report);}

    [Fact]public void DifferentClockChunkSizesKeepSameAgreedDepartureAndRoute(){var a=Start();var b=Start();Assign(a);Assign(b);Advance(a,120);for(int at=1;at<=120;at++)Advance(b,at);var left=a.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier);var right=b.DiagnosticSnapshot().Branches!.Journeys.Single(j=>j.Actor==Carrier);Assert.Equal(61,left.Legs[0].StartAt);Assert.Equal(ContractJson.Write(left.Legs),ContractJson.Write(right.Legs));Assert.Equal(RegionalCampaign.ActorPointAt(a.DiagnosticSnapshot(),Carrier,120),RegionalCampaign.ActorPointAt(b.DiagnosticSnapshot(),Carrier,120));Assert.Equal(Current(a).Cargo,Current(b).Cargo);Assert.Equal(Current(a).Cash,Current(b).Cash);}
}
